 async Task<JsonObject> Login(JsonObject user){var id=Id();var exp=DateTimeOffset.UtcNow.AddHours(1);await s.Save("sessions",Obj(new{id,userId=user.S("id"),expires=exp.ToUnixTimeSeconds(),revoked=false}));var key=configuration["Jwt:Key"]!;var token=new JwtSecurityToken("CampusFix.Api","CampusFix.Angular",[new("sub",user.S("id")),new("stamp",user.S("stamp")),new("jti",id),new(ClaimTypes.Role,user.S("role"))],expires:exp.UtcDateTime,signingCredentials:new(new SymmetricSecurityKey(Encoding.UTF8.GetBytes(key)),SecurityAlgorithms.HmacSha256));var result=Public(user);result["permissions"]=await Effective(s,user);result["token"]=new JwtSecurityTokenHandler().WriteToken(token);return result;}
 public async Task<object> Run(string path,string method,JsonObject b,ClaimsPrincipal principal,IQueryCollection query){
