  Require(!u.B("mustChange"),403,"Debes cambiar tu contraseña antes de continuar.");
  if(path=="data"&&method=="GET"){
   var ts=(await RoutedTickets()).Where(t=>!t.B("eliminado")&&See(u,p,t)).ToList();var users=await s.All("users");var configs=await s.All("config");foreach(var c in configs)c["fields"]=Arr(c.A("fields").Items().Where(f=>p.B("internos")||!f.B("internal")));var articles=(await s.All("articles")).Where(a=>ReadArticle(a,p)).ToList();foreach(var a in articles){if(!p.B("gestionarConocimiento"))a.Remove("versions");else a["versions"]=Arr(a.A("versions").Items().Where(v=>p.B("internos")||v.S("visibility")=="usuarios"&&v.S("status")=="Publicado"));}var me=Public(u);me["permissions"]=p.Copy();return new{user=me,tickets=ts.Select(t=>SafeTicket(t,p)),users=await Directory(ts),config=configs,articles,notifications=Notifications(await s.All("notifications"),ts)};
  }
  if(path=="usuarios"&&method=="GET"){Need("usuarios");Require(Admin(u),403,"Acción reservada a administración.");return await Directory((await RoutedTickets()).Where(t=>See(u,p,t)).ToList());}
  if(path=="usuarios"&&method=="POST"){Need("gestionarUsuarios");Require(Admin(u),403,"Acción reservada a administración.");var role=b.S("role","Solicitante");if(role!="Solicitante")Owner();Require(Roles.Contains(role)&&role!="Superadministrador",400,"Rol no permitido para nuevas cuentas.");var email=Email(b);var pw=Password(b);Require(await s.Get("users",email)==null,409,"Ese correo ya está registrado.");var areas=await UserAreas(b,null);var person=Merge(areas,Obj(new{id=email,correo=email,nombre=Required(b,"nombre","Nombre",120),role,activo=true,passwordHash=Hash(pw),stamp=Id(),mustChange=true,created=Now()}));person=await s.Save("users",person);await Audit("Usuario creado",email);return Public(person);}
  if(path.StartsWith("usuarios/")&&method=="PUT"){Need("gestionarUsuarios");var parts=path.Split('/');var person=await s.Get("users",Uri.UnescapeDataString(parts[1]));Require(person!=null,404,"Usuario no encontrado.");Require(ManagePerson(person!),403,"No administras el área operativa de esta cuenta.");Version(person,b);Require(!(person!.S("role")=="Superadministrador"&&u.S("id")!=person.S("id"))&&(u.S("role")=="Superadministrador"||person.S("role") is "Solicitante" or "Técnico"),403,"Cuenta protegida.");bool reset=parts.Length==3&&parts[2]=="reset";if(reset){Require(person.S("role")!="Superadministrador",403,"Usa Mi cuenta para cambiar tu contraseña.");person["passwordHash"]=Hash(Password(b));person["mustChange"]=true;person["failures"]=0;person["lockUntil"]=null;}else{Require(parts.Length==2,404,"Ruta no encontrada.");person["nombre"]=Required(b,"nombre","Nombre",120);if(b.S("role")!=""&&b.S("role")!=person.S("role")){Owner();Require(Roles.Contains(b.S("role"))&&person.S("role")!="Superadministrador"&&b.S("role")!="Superadministrador",403,"No se puede transferir el rol de propietario.");person["role"]=b.S("role");}Require(person.S("role")!="Superadministrador"||b.B("activo",true),400,"No puedes desactivar al propietario.");if(b.ContainsKey("activo"))person["activo"]=b.B("activo");person=Merge(person,await UserAreas(b,person));}person["stamp"]=Id();person=await s.Save("users",person);await Audit(reset?"Contraseña restablecida":"Usuario actualizado",person.S("id"));return Public(person);}
  if(path=="permisos")return await RoleApi(method,b);
  if(path=="config"&&method=="POST")return await ConfigApi(b);
  if(path=="config/template"&&method=="POST"){Need("gestionarConfiguracion");Owner();foreach(var (kind,names) in new[]{("areas",new[]{"Bienestar estudiantil","Admisiones","Registro Académico","Secretaría Académica","Tecnologías de la Información","Mantenimiento"}),("sedes",new[]{"Campus principal","Campus norte"}),("servicios",new[]{"Soporte tecnológico","Mantenimiento"})})foreach(var name in names){var id="plantilla-"+kind+"-"+name;if(await s.Get("config",id)==null)await s.Save("config",Obj(new{id,kind,nombre=name,activo=true,fields=Array.Empty<object>()}));}await Audit("Plantilla universitaria cargada","config");return new{ok=true};}
  if(path=="reportes"&&method=="GET"){Need("tablero");return (await RoutedTickets()).Where(t=>!t.B("eliminado")&&See(u,p,t)).Select(t=>SafeTicket(t,p));}
