  if(path=="notifications"&&method=="PUT"){foreach(var n in (await s.All("notifications")).Where(n=>n.S("userId")==u.S("id")&&(b.B("all")||n.S("id")==b.S("id")))){n["read"]=b.B("read",true);await s.Save("notifications",n);}return new{ok=true};}
