 async Task<JsonObject> UserAreas(JsonObject b,JsonObject? old){var areas=Strings(b["areas"]??old?["areas"]??new JsonArray(),"Áreas");var active=(await s.All("config")).Where(c=>c.S("kind")=="areas"&&c.B("activo")).Select(c=>c.S("id")).ToHashSet();Require(areas.All(a=>active.Contains(a!.ToString())||old.A("areas").Has(a.ToString())),400,"Área no válida o inactiva.");var id=b.S("areaId",old.S("areaId"));Require(id==""||areas.Has(id),400,"El área principal debe estar entre las áreas autorizadas.");var operational=Strings(b["operationalAreas"]??old?["operationalAreas"]??new JsonArray(),"Áreas operativas");Require(operational.All(a=>active.Contains(a!.ToString())||old.A("operationalAreas").Has(a.ToString())),400,"Área operativa no válida.");if(u.S("role")!="Superadministrador"){Require(areas.All(a=>p.A("managedAreas").Has(a!.ToString()))&&operational.All(a=>p.A("managedAreas").Has(a!.ToString())),403,"Solo puedes administrar personal de tus áreas.");}return Obj(new{areas,areaId=id,operationalAreas=operational});}
 async Task<object> RoleApi(string method,JsonObject b){Owner();if(method=="GET"){var roles=new List<JsonObject>();foreach(var role in Roles){var saved=await s.Get("roles",role);roles.Add(Obj(new{role,version=saved?["_v"]?.DeepClone(),permissions=Merge(Defaults(role),saved.O("permissions"))}));}return new{roles,users=(await s.All("users")).Select(Public),audit=(await s.All("audit")).OrderByDescending(a=>a.S("fecha")).Take(200),keys=Keys};}Require(method=="PUT",405,"Operación no permitida.");Require(b.S("type") is "role" or "user"&&b["permissions"] is JsonObject,400,"Permisos no válidos.");var clean=new JsonObject();foreach(var key in Keys)if(b.O("permissions")[key] is JsonValue j&&j.TryGetValue<bool>(out var value))clean[key]=value;var scope=b.S("scope");Require(scope==""||scope is "propios" or "asignados" or "todos" or "areas",400,"Alcance inválido.");var id=b.S("id");if(b.S("type")=="role"){Require(Roles.Contains(id)&&id!="Superadministrador",403,"Rol protegido.");var old=await s.Get("roles",id);Version(old,b);clean["scope"]=scope==""?Defaults(id).S("scope"):scope;await s.Save("roles",Merge(old??new(),Obj(new{id,permissions=clean})));foreach(var person in (await s.All("users")).Where(x=>x.S("role")==id)){person["stamp"]=Id();await s.Save("users",person);}}else{var person=await s.Get("users",id);Require(person!=null&&person.S("role")!="Superadministrador",403,"Cuenta protegida.");Version(person,b);person!["permissions"]=b.B("reset")?new JsonObject():clean;person["scope"]=b.B("reset")?"":scope;person["stamp"]=Id();await s.Save("users",person);}await Audit("Permisos actualizados",id);return new{ok=true};}
